package com.example.controllers;
import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.example.dtos.*; import com.example.services.PedidoService; import Enum.StatusPedido;
@RestController @RequestMapping("/pedidos") public class PedidoController {private final PedidoService service;public PedidoController(PedidoService service){this.service=service;}@GetMapping public List<PedidoResponseDTO> listar(){return service.listarTodos();}@GetMapping("/{id}") public ResponseEntity<PedidoResponseDTO> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));}@PostMapping("/checkout") public ResponseEntity<PedidoResponseDTO> checkout(@RequestBody PedidoRequestDTO d){return ResponseEntity.ok(service.checkout(d));}@PatchMapping("/{id}/status") public ResponseEntity<Void> status(@PathVariable Long id,@RequestParam StatusPedido status){service.atualizarStatus(id,status);return ResponseEntity.noContent().build();}@PostMapping("/{id}/cancelar") public ResponseEntity<Void> cancelar(@PathVariable Long id){service.cancelar(id);return ResponseEntity.noContent().build();}}
